// launch-factory: 관리자 조립. 관리자 벽(role=admin + 2단계 인증 켬 + 대리 세션 아님)과 행동 기록(admin_actions)은 @launch-factory/auth 가 갖는다.
// 이 파일은 요청 하나에 붙는 입출력(쿠키)·DB·인증 처리기를 묶을 뿐이다. 관리자 조각이 꺼져 있으면(lib/launch/features.ts) 열리지 않고 이유를 알린다.
import { adminActions, type AdminActions } from "@launch-factory/auth"
import { authIO, getAuth } from "@/lib/launch/auth"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { AUTH_FEATURES } from "@/lib/launch/features"

/** 관리자 조각이 꺼져 있다 — AUTH_FEATURES 를 { twoFactor: true, admin: true } 로 바꿔야 한다 */
export class AdminDisabledError extends Error {
  constructor() {
    super("admin feature is off: set AUTH_FEATURES to { twoFactor: true, admin: true } in lib/launch/features.ts")
    this.name = "AdminDisabledError"
  }
}

export async function admin(): Promise<AdminActions> {
  if (!AUTH_FEATURES.admin || !AUTH_FEATURES.twoFactor) throw new AdminDisabledError()
  return adminActions({ auth: await getAuth(), db: await database(), io: await authIO(), locale: DEFAULT_LOCALE })
}

/** 꺼져 있으면 503 unavailable 로 닫는다(조용히 성공하지도, 500 으로 새지도 않는다) */
export async function runAdmin<T>(run: (actions: AdminActions) => Promise<T>) {
  try {
    return await run(await admin())
  } catch (e) {
    if (e instanceof AdminDisabledError) return { ok: false as const, status: 503 as const, code: "unavailable" as const, formError: e.message }
    throw e
  }
}

"use server"
// launch-factory: 관리자 서버 액션. 서버 액션은 누구나 부를 수 있는 공개 입구다 — 모든 액션이 먼저 관리자 벽(관리자 + 2단계 인증 + 대리 세션 아님)을 지난다.
// 화면(표·상세)은 제품이 web-factory 블록으로 짠다. 읽기(목록·상세·CSV)는 admin_actions 에 남고, 쓰기(정지·해제·대리 로그인)는 Better Auth 훅이 남긴다.
import { runAdmin } from "@/lib/launch/admin"

export async function listUsers(input?: unknown) {
  return runAdmin((a) => a.listUsers(input))
}

export async function userDetail(input: unknown) {
  return runAdmin((a) => a.userDetail(input))
}

/** 정지는 사람 확인이 필요하다 — input.confirmed 가 정확히 true 가 아니면 confirmation_required(콘솔 구획의 정지와 같은 벽) */
export async function banUser(input: unknown) {
  return runAdmin((a) => a.banUser(input))
}

export async function unbanUser(input: unknown) {
  return runAdmin((a) => a.unbanUser(input))
}

/** 일괄 정지도 input.confirmed: true 가 필요하다 */
export async function bulkBan(input: unknown) {
  return runAdmin((a) => a.bulkBan(input))
}

export async function bulkUnban(input: unknown) {
  return runAdmin((a) => a.bulkUnban(input))
}

/** 대리 로그인은 사유가 필수다. 시작·종료가 모두 admin_actions 에 남는다 */
export async function impersonate(input: unknown) {
  return runAdmin((a) => a.impersonate(input))
}

export async function stopImpersonating() {
  return runAdmin((a) => a.stopImpersonating())
}

// launch-factory: 사용자 CSV 내려받기(GET). 관리자 벽을 지난 요청만 받는다 — 로그인 안 함 401, 관리자 아님·2단계 없음 403, 꺼져 있음 503.
// 질의: ?q=검색어&banned=true|false&role=admin|user&sort=createdAt|email|name&dir=asc|desc. BOM·수식 무력화·서울 시각(대장 D90). 내려받기는 admin_actions 에 남는다.
import { runAdmin } from "@/lib/launch/admin"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  const p = new URL(request.url).searchParams
  const filter: Record<string, string> = {}
  if (p.get("banned")) filter.banned = p.get("banned") ?? ""
  if (p.get("role")) filter.role = p.get("role") ?? ""
  const input: Record<string, unknown> = {}
  if (p.get("q")) input.q = p.get("q")
  if (Object.keys(filter).length) input.filter = filter
  if (p.get("sort")) input.sort = { field: p.get("sort"), dir: p.get("dir") ?? "desc" }
  const r = await runAdmin((a) => a.exportUsersCsv(input))
  if (!r.ok) return Response.json(r, { status: r.status, headers: { "cache-control": "no-store" } })
  return new Response(r.data.body, {
    headers: { "content-type": r.data.contentType, "content-disposition": `attachment; filename="${r.data.filename}"`, "cache-control": "no-store" },
  })
}

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

/**
 * mock 의 메모리 DB 는 프로세스 하나에 하나다. 서버 번들은 쪽·서버 액션·경로 처리기(app/api)로 갈라져 같은 모듈이 번들마다 따로 불리므로(Next/Turbopack),
 * 모듈 변수에만 두면 번들 수만큼 DB 가 생겨 경로 처리기(웹훅·크론·/api/auth)와 쪽이 서로 다른 데이터를 보았다(관리 화면 시험 실측: 경로로 만든 세션이 쪽에서 안 보였다).
 * 그래서 globalThis 에 둔다. live 는 연결 문자열이 같은 DB 를 가리키므로 모듈 변수로 충분하다.
 */
const mockStore = globalThis as { __lfMockDb?: Promise<Database> }

export function database(): Promise<Database> {
  if (env().LF_MODE === "mock") return (mockStore.__lfMockDb ??= db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }))
  return (cached ??= Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}
